template <typename T>
T mod_inverse(T a, T m) {
  T u = 0, v = 1;
  while (a != 0) {
    T t = m / a;
    m -= t * a; swap(a, m);
    u -= t * v; swap(u, v);
  }
  assert(m == 1);
  return u;
}

template <typename T>
class ModNumber {
 public:
  using Type = typename decay<decltype(T::value)>::type;

  ModNumber() : val() {}
  template <typename U>
  ModNumber(const U& x) {
    val = normalize(x);
  }

  static Type normalize(const U& x) {
    Type v;
    if (-mod() <= x && x < mod()) v = static_cast<Type>(x);
    else v = static_cast<Type>(x % mod());
    if (v < 0) v += mod();
    return v;
  }

  const Type& get() const { return val; }
  explicit operator Type() const { return val; }
  static constexpr Type mod() { return T::value; }

  ModNumber& operator+=(const ModNumber& other) {
    if ((val += other.val) >= mod()) val -= mod();
    return *this;
  }
  ModNumber& operator-=(const ModNumber& other) {
    if ((val -= other.val) < 0) val += mod();
    return *this;
  }
  template <typename U> ModNumber& operator+=(const U& other) { return *this += ModNumber(other); }
  template <typename U> ModNumber& operator-=(const U& other) { return *this -= ModNumber(other); }
  ModNumber& operator++() { return *this += 1; }
  ModNumber& operator--() { return *this -= 1; }
  ModNumber operator++(int) { ModNumber tmp(*this); *this += 1; return tmp; }
  ModNumber operator--(int) { ModNumber tmp(*this); *this -= 1; return tmp; }
  ModNumber operator-() const { return ModNumber(-val); }

  template <typename U = T>
  typename enable_if<is_same<typename ModNumber<U>::Type, int>::value, ModNumber>::type& operator*=(const ModNumber& rhs) {
#ifdef _WIN32
    uint64_t x = static_cast<int64_t>(val) * static_cast<int64_t>(rhs.val);
    uint32_t xh = static_cast<uint32_t>(x >> 32), xl = static_cast<uint32_t>(x), d, m;
    asm(
      "divl %4; \n\t"
      : "=a" (d), "=d" (m)
      : "d" (xh), "a" (xl), "r" (mod())
    );
    val = m;
#else
    val = normalize(static_cast<int64_t>(val) * static_cast<int64_t>(rhs.val));
#endif
    return *this;
  }
  template <typename U = T>
  typename enable_if<is_same<typename ModNumber<U>::Type, int64_t>::value, ModNumber>::type& operator*=(const ModNumber& rhs) {
    int64_t q = static_cast<int64_t>(static_cast<long double>(val) * rhs.val / mod());
    val = normalize(val * rhs.val - q * mod());
    return *this;
  }
  template <typename U = T>
  typename enable_if<!is_integral<typename ModNumber<U>::Type>::value, ModNumber>::type& operator*=(const ModNumber& rhs) {
    val = normalize(val * rhs.val);
    return *this;
  }

  ModNumber& operator/=(const ModNumber& other) { return *this *= ModNumber(mod_inverse(other.val, mod())); }

  friend bool operator==(const ModNumber& lhs, const ModNumber& rhs) { return lhs.val == rhs.val; }
  friend bool operator<(const ModNumber& lhs, const ModNumber& rhs) { return lhs.val < rhs.val; }

  friend std::istream& operator>>(std::istream& in, ModNumber& num) {
    typename common_type<typename ModNumber::Type, int64_t>::type x;
    in >> x;
    num.val = normalize(x);
    return in;
  }

 private:
  Type val;
};

using ModType2 = int;
struct MyMod { static ModType2 value; };
ModType2 MyMod::value;
using Number = ModNumber<MyMod>;

int main() {
  int n, m;
  cin >> n >> m >> MyMod::value;
  vector<Number> fact = {1};
  vector<Number> inv_fact = {1};
  auto C = [&](int x, int y) {
    int sz = max(x, y);
    while ((int)fact.size() <= sz) {
      fact.push_back(fact.back() * (int)fact.size());
      inv_fact.push_back(1 / fact.back());
    }
    if (y < 0 || y > x) return Number(0);
    return fact[x] * inv_fact[y] * inv_fact[x - y];
  };
  vector<Number> ways_arr(m + 1, 0), ways_count(m + 1, 0);
  ways_count[0] = 1;
  for (int i = 1; i <= m; ++i) {
    for (int j = 0; j < i; ++j) {
      int l = j, r = i - 1 - j;
      ways_arr[i] += ways_count[l] * ways_count[r] * C(l + r, l) * Number(l + r + 2);
    }
    for (int j = 0; j < i; ++j) {
      int l = j, r = i - 1 - j;
      Number add = (Number(l) * (l + 1) + Number(r) * (r + 1)) / 2;
      ways_count[i] += ways_count[l] * ways_count[r] * C(l + r, l) * add;
    }
  }
  vector<vector<Number>> dp(n + 1, vector<Number>(m + 1, 0));
  vector<vector<Number>> ways_dp(n + 1, vector<Number>(m + 1, 0));
  ways_dp[0][0] = 1;
  for (int i = 1; i <= n; ++i) {
    for (int s = 0; s <= min(m, i); ++s) {
      if (s == i) {
        dp[i][s] = ways_count[s];
        continue;
      }
      for (int d = 1; d <= s + 1; ++d) {
        Number ft = dp[i - d][s + 1 - d];
        Number way = ways_dp[i - d][s + 1 - d];
        int add = d - 1;
        ways_dp[i][s] += way * ways_count[add] * C(s, add);
        dp[i][s] += (way * ways_count[add] + ways_dp[i - d][s + 1 - d] * ft) * C(s, add);
      }
    }
  }
  cout << dp[n][m];
  return 0;
}
